import {readFileSync,mkdtempSync,writeFileSync,truncateSync,rmSync} from 'node:fs';
import {join} from 'node:path';
import {tmpdir} from 'node:os';
import {test,expect} from './fixtures.ts';
import {canonicalState as state,openPanel,closePanel,ready} from './browser-helpers.ts';

// Generated by P5_27_every_minute_reopen_preserves_exact_continuation from
// gameplay-built rails, purchased formations and validated deployment.
const input=process.env.FREETRAIN_FLEET_CONTINUATION_OUTPUT;
for(const locale of ['en','ja'] as const)test(`P5-27 ${locale} fleet slot download rejected uploads reconnect and process restart match uninterrupted run`,async({page,browser,baseURL,worldServer})=>{
 test.skip(!input,'Set FREETRAIN_FLEET_CONTINUATION_OUTPUT when running the P5_27 unit matrix first.');
 test.setTimeout(120000);
 const original=readFileSync(input!),expected=readFileSync(input!+'.expected');
 const text=JSON.parse(readFileSync(`src/locales/${locale}/app.json`,'utf8'));
 const saved=async()=>(await page.request.get('/api/saves/download')).body();
 const button=(name:string)=>page.getByRole('button',{name,exact:true});
 const errors:string[]=[];page.on('pageerror',e=>errors.push(String(e)));
 const secret=process.env.FREETRAIN_ONLINE_TEST_CONTAINER_IMAGE?'fleet-container-test':'';
 if(secret)expect((await page.request.post('/api/access',{data:{secret}})).ok()).toBe(true);
 await page.goto('/');await ready(page);
 const before=await state(page);
 expect((await page.request.post('/api/saves/upload?expectedWorldEpoch='+before.worldEpoch,{data:original})).ok()).toBe(true);
 await page.reload();await ready(page);
 if(locale==='ja'){
  await openPanel(page,'settings');await page.getByLabel('Language',{exact:true}).selectOption('ja');await closePanel(page);await ready(page,'ja');
 }
 const context=await browser.newContext({baseURL,locale:'ja-JP'}),peer=await context.newPage();
 try{
  if(secret)expect((await peer.request.post('/api/access',{data:{secret:'observer-test'}})).ok()).toBe(true);
  await peer.goto('/');await ready(peer,'ja');
  await openPanel(page,'saves',locale);await page.getByLabel(text.saveSlot,{exact:true}).selectOption('slot2');
  await button(text.saveGame).click();await expect(page.getByTestId('save-feedback')).toHaveText(text.saved);
  const [download]=await Promise.all([page.waitForEvent('download'),button(text.downloadSave).click()]);
  expect(readFileSync((await download.path())!)).toEqual(original);
  const epoch=(await state(page)).worldEpoch;
  const badVersion=JSON.parse(original.toString());badVersion.saveVersion=8;
  const badPack=JSON.parse(original.toString());badPack.requiredPacks[0].catalogHash='0'.repeat(64);
  const badGraph=JSON.parse(original.toString());badGraph.mixed.fleet.trains[0].controllerId='999999';
  for(const [buffer,message] of [[Buffer.from('{broken'),text.invalidSave],[Buffer.from(JSON.stringify(badVersion)),text.incompatibleSave],
   [Buffer.from(JSON.stringify(badPack)),text.incompatibleSave],[Buffer.from(JSON.stringify(badGraph)),text.invalidSave]] as const){
   const upload=page.getByLabel(text.uploadSave,{exact:true});await expect(upload).toBeEnabled();
   await upload.setInputFiles({name:'rejected-fleet.json',mimeType:'application/json',buffer});
   await expect(page.getByTestId('save-feedback')).toContainText(message);
   expect(await saved()).toEqual(original);expect((await state(page)).worldEpoch).toBe(epoch);
   await expect(page.locator('.decision-dialog')).toHaveCount(0);
  }
  const directory=mkdtempSync(join(tmpdir(),'fleet-oversize-')),large=join(directory,'large.json');
  try{
   writeFileSync(large,'x');truncateSync(large,256*1024*1024+1);
   const upload=page.getByLabel(text.uploadSave,{exact:true});await expect(upload).toBeEnabled();await upload.setInputFiles(large);
   await expect(page.getByTestId('save-feedback')).toHaveText(text.saveTooLarge);expect(await saved()).toEqual(original);
  }finally{rmSync(directory,{recursive:true,force:true});}
  // Rejected uploads must leave the named file intact as well as the live world.
  await button(text.loadGame).click();await button(text.confirmLoad).click();await ready(page,locale);
  expect(await saved()).toEqual(original);
  await openPanel(page,'session',locale);await button(text.reconnect).click();await ready(page,locale);
  await expect.poll(async()=>(await state(peer)).mixed).toEqual((await state(page)).mixed);
  await worldServer.restart!();
  for(const p of [page,peer])expect((await p.request.post('/api/access',{data:{secret:p===peer&&secret?'observer-test':secret}})).ok()).toBe(true);
  await page.reload();await ready(page,locale);await peer.reload();await ready(peer,'ja');
  expect(await saved()).toEqual(original);
  // The unit oracle ran uninterrupted from100 to116. Recovered process must
  // reproduce every byte, including all sixteen one-shot registrations/charges.
  for(let minute=101;minute<=116;minute++){
   await page.getByRole('button',{name:text.step,exact:false}).first().click();
   await expect.poll(async()=>(await state(peer)).tick).toBe(String(minute));
  }
  expect(await saved()).toEqual(expected);
  await expect.poll(async()=>(await state(peer)).mixed).toEqual(JSON.parse(expected.toString()).mixed);
  expect(errors).toEqual([]);
 }finally{await context.close();}
});
